-- Dah Glow private control and receipt support. No existing user data is deleted or changed.

create table if not exists public.dg_admin_roles (name text primary key, permissions text[] not null);
insert into public.dg_admin_roles values ('super_admin',array['overview','products','store','vendors','orders','customers','analytics','admins','settings']),('store_manager',array['products','store','vendors']),('orders_manager',array['orders']),('analytics_viewer',array['overview','analytics']),('custom','{}') on conflict do nothing;
create table if not exists public.dg_admin_allowlist (email text primary key check(email=lower(trim(email))),role text not null references public.dg_admin_roles(name),permissions text[] not null default '{}',active boolean not null default true,initial boolean not null default false,created_at timestamptz not null default now());
insert into public.dg_admin_allowlist(email,role,initial) values('berryxoe@gmail.com','super_admin',true),('dawiniefleury07@gmail.com','super_admin',true) on conflict do nothing;
create table if not exists public.dg_admin_profiles (user_id uuid primary key references public.user_profiles(id) on delete cascade,display_name text not null default '',avatar_url text,notifications boolean not null default true);
create table if not exists public.dg_admin_invitations (id uuid primary key default gen_random_uuid(),email text not null,role text not null references public.dg_admin_roles(name),permissions text[] not null default '{}',invited_by uuid not null references public.user_profiles(id),expires_at timestamptz not null default(now()+interval '7 days'),accepted_at timestamptz,revoked_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.dg_admin_config (id boolean primary key default true check(id),route_segment text not null default replace(gen_random_uuid()::text||gen_random_uuid()::text,'-',''));
insert into public.dg_admin_config(id) values(true) on conflict do nothing;
create table if not exists public.dg_store_settings (id boolean primary key default true check(id),payload jsonb not null default '{}',updated_at timestamptz not null default now());
insert into public.dg_store_settings(id) values(true) on conflict do nothing;
create table if not exists public.dg_vendor_settings (vendor text primary key,display_name text,description text,avatar_url text,visible boolean not null default true,business_email text,business_address text);
create table if not exists public.dg_product_visibility (product_id text primary key,visible boolean not null default true);
create table if not exists public.dg_admin_activity (id uuid primary key default gen_random_uuid(),actor_id uuid not null references public.user_profiles(id),action text not null,resource text,details jsonb not null default '{}',created_at timestamptz not null default now());
create table if not exists public.dg_admin_analytics_cache (cache_key text primary key,payload jsonb not null,expires_at timestamptz not null);
create table if not exists public.dg_rate_limits (key text primary key,window_start timestamptz not null default now(),count integer not null default 1);
create table if not exists public.dg_order_receipts (user_id uuid not null references public.user_profiles(id) on delete cascade,order_id text not null references public.dg_orders(id),confirmed_at timestamptz not null default now(),primary key(user_id,order_id));
create table if not exists public.dg_order_activity (event_id text primary key,topic text not null,order_id text,order_name text,customer_name text,total jsonb,financial_status text,created_at timestamptz not null default now());
create or replace function public.dg_has_permission(p_permission text) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from dg_admin_allowlist a join dg_admin_roles r on r.name=a.role where a.email=lower(coalesce(auth.jwt()->>'email','')) and a.active and (p_permission=any(r.permissions) or p_permission=any(a.permissions)) and exists(select 1 from auth.users u where u.id=auth.uid() and u.email_confirmed_at is not null)); $$;
revoke all on function public.dg_has_permission(text) from public,anon;
grant execute on function public.dg_has_permission(text) to authenticated,service_role;
create or replace function public.dg_rate_check(p_key text,p_limit integer,p_seconds integer) returns boolean language plpgsql security definer set search_path=public as $$ declare n integer; begin insert into dg_rate_limits(key) values(p_key) on conflict(key) do update set count=case when dg_rate_limits.window_start<now()-make_interval(secs=>p_seconds) then 1 else dg_rate_limits.count+1 end,window_start=case when dg_rate_limits.window_start<now()-make_interval(secs=>p_seconds) then now() else dg_rate_limits.window_start end returning count into n; return n<=p_limit; end; $$;
revoke all on function public.dg_rate_check(text,integer,integer) from public,anon,authenticated;
grant execute on function public.dg_rate_check(text,integer,integer) to service_role;
do $$ declare t text; begin foreach t in array array['dg_admin_roles','dg_admin_allowlist','dg_admin_profiles','dg_admin_invitations','dg_admin_config','dg_store_settings','dg_vendor_settings','dg_product_visibility','dg_admin_activity','dg_admin_analytics_cache','dg_rate_limits','dg_order_receipts','dg_order_activity'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end $$;
grant select on public.dg_admin_profiles,public.dg_admin_invitations,public.dg_admin_roles,public.dg_admin_activity,public.dg_store_settings,public.dg_vendor_settings,public.dg_product_visibility,public.dg_order_receipts,public.dg_order_activity to authenticated;
-- Independent select policies; all management writes are service-only behind Edge authorization.
do $$ declare spec record; begin for spec in select * from (values ('dg_admin_profiles','authenticated_select_admin_profiles','public.dg_has_permission(''admins'') or (user_id=auth.uid() and public.dg_has_permission(''settings''))'),('dg_admin_invitations','authenticated_select_admin_invitations','public.dg_has_permission(''admins'')'),('dg_admin_roles','authenticated_select_admin_roles','public.dg_has_permission(''admins'')'),('dg_admin_activity','authenticated_select_admin_activity','public.dg_has_permission(''overview'')'),('dg_store_settings','authenticated_select_store_settings','public.dg_has_permission(''store'')'),('dg_vendor_settings','authenticated_select_vendor_settings','public.dg_has_permission(''vendors'')'),('dg_product_visibility','authenticated_select_product_visibility','public.dg_has_permission(''products'')'),('dg_order_receipts','authenticated_select_own_receipts','user_id=auth.uid()'),('dg_order_activity','authenticated_select_admin_order_activity','public.dg_has_permission(''overview'')')) as p(tbl,policy_name,expression) loop if not exists(select 1 from pg_policies where schemaname='public' and tablename=spec.tbl and policyname=spec.policy_name) then execute format('create policy %I on public.%I for select to authenticated using(%s)',spec.policy_name,spec.tbl,spec.expression);end if;end loop;end $$;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('dg-branding','dg-branding',true,5242880,array['image/jpeg','image/png','image/webp']) on conflict do nothing;
do $$ begin if not exists(select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='anon_select_branding') then create policy anon_select_branding on storage.objects for select to anon using(bucket_id='dg-branding');end if;if not exists(select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='authenticated_select_branding') then create policy authenticated_select_branding on storage.objects for select to authenticated using(bucket_id='dg-branding');end if;if not exists(select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='authenticated_insert_branding') then create policy authenticated_insert_branding on storage.objects for insert to authenticated with check(bucket_id='dg-branding' and (public.dg_has_permission('store') or public.dg_has_permission('vendors') or public.dg_has_permission('settings')));end if;end $$;
